import org.apache.commons.lang3.time.DateUtils;
import java.util.*;
import java.text.*;

public class Explore {
    public static void main(String[] args) throws Exception {
        TimeZone.setDefault(TimeZone.getTimeZone("America/Los_Angeles"));
        Calendar cal = Calendar.getInstance();
        cal.clear();
        cal.set(2002, Calendar.MARCH, 28, 13, 45, 1);
        cal.set(Calendar.MILLISECOND, 231);
        Date d = cal.getTime();

        System.out.println("ceiling HOUR_OF_DAY: " + DateUtils.ceiling(d, Calendar.HOUR_OF_DAY));
        System.out.println("ceiling MONTH: " + DateUtils.ceiling(d, Calendar.MONTH));
        System.out.println("truncate HOUR_OF_DAY: " + DateUtils.truncate(d, Calendar.HOUR_OF_DAY));
        System.out.println("truncate MONTH: " + DateUtils.truncate(d, Calendar.MONTH));
        System.out.println("round HOUR_OF_DAY: " + DateUtils.round(d, Calendar.HOUR_OF_DAY));
        System.out.println("round MONTH: " + DateUtils.round(d, Calendar.MONTH));

        // SEMI_MONTH test
        Calendar c2 = Calendar.getInstance();
        c2.clear();
        c2.set(2002, Calendar.MARCH, 1, 0, 0, 0);
        System.out.println("round SEMI_MONTH day1: " + DateUtils.round(c2.getTime(), DateUtils.SEMI_MONTH));
        c2.set(2002, Calendar.MARCH, 10, 0, 0, 0);
        System.out.println("round SEMI_MONTH day10: " + DateUtils.round(c2.getTime(), DateUtils.SEMI_MONTH));
        c2.set(2002, Calendar.MARCH, 20, 0, 0, 0);
        System.out.println("round SEMI_MONTH day20: " + DateUtils.round(c2.getTime(), DateUtils.SEMI_MONTH));
        c2.set(2002, Calendar.MARCH, 28, 0, 0, 0);
        System.out.println("round SEMI_MONTH day28: " + DateUtils.round(c2.getTime(), DateUtils.SEMI_MONTH));

        // AM_PM round
        Calendar c3 = Calendar.getInstance();
        c3.clear();
        c3.set(2002, Calendar.MARCH, 28, 11, 0, 0);
        System.out.println("round AM_PM 11:00: " + DateUtils.round(c3.getTime(), Calendar.AM_PM));
        c3.set(2002, Calendar.MARCH, 28, 13, 0, 0);
        System.out.println("round AM_PM 13:00: " + DateUtils.round(c3.getTime(), Calendar.AM_PM));
        c3.set(2002, Calendar.MARCH, 28, 23, 0, 0);
        System.out.println("round AM_PM 23:00: " + DateUtils.round(c3.getTime(), Calendar.AM_PM));

        // parseDateStrictly vs parseDate with overflow day
        try {
            Date pd = DateUtils.parseDate("20090229", "yyyyMMdd"); // 2009 not leap year
            System.out.println("parseDate lenient 20090229 -> " + pd);
        } catch (ParseException e) { System.out.println("parseDate lenient threw: " + e); }
        try {
            Date pd = DateUtils.parseDateStrictly("20090229", "yyyyMMdd");
            System.out.println("parseDateStrictly 20090229 -> " + pd);
        } catch (ParseException e) { System.out.println("parseDateStrictly threw: " + e); }

        // iterator RANGE_WEEK_CENTER
        Calendar focus = Calendar.getInstance();
        focus.clear();
        focus.set(2002, Calendar.JULY, 4); // Thursday
        Iterator<Calendar> it = DateUtils.iterator(focus, DateUtils.RANGE_WEEK_CENTER);
        System.out.print("RANGE_WEEK_CENTER: ");
        while (it.hasNext()) {
            Calendar c = it.next();
            System.out.print(new SimpleDateFormat("yyyy-MM-dd(E)").format(c.getTime()) + " ");
        }
        System.out.println();

        Iterator<Calendar> it2 = DateUtils.iterator(focus, DateUtils.RANGE_MONTH_SUNDAY);
        System.out.print("RANGE_MONTH_SUNDAY count: ");
        int cnt=0; Calendar first=null, last=null;
        while (it2.hasNext()) { last = it2.next(); if(first==null) first=last; cnt++; }
        System.out.println(cnt + " first=" + new SimpleDateFormat("yyyy-MM-dd").format(first.getTime()) + " last=" + new SimpleDateFormat("yyyy-MM-dd").format(last.getTime()));

        // getFragment examples from doc
        Calendar fc = Calendar.getInstance();
        fc.clear();
        fc.set(2008, Calendar.JANUARY, 28);
        System.out.println("Jan28 2008 getFragmentInDays MONTH: " + DateUtils.getFragmentInDays(fc, Calendar.MONTH));
        fc.clear();
        fc.set(2008, Calendar.FEBRUARY, 28);
        System.out.println("Feb28 2008 getFragmentInDays YEAR: " + DateUtils.getFragmentInDays(fc, Calendar.YEAR));

        fc.clear();
        fc.set(2008, Calendar.JANUARY, 1, 7, 15, 10);
        fc.set(Calendar.MILLISECOND, 538);
        System.out.println("getFragmentInHours DAY_OF_YEAR: " + DateUtils.getFragmentInHours(fc, Calendar.DAY_OF_YEAR));
        fc.set(2008, Calendar.JANUARY, 6, 7, 15, 10);
        System.out.println("getFragmentInHours MONTH (jan6): " + DateUtils.getFragmentInHours(fc, Calendar.MONTH));

        // setDays out of range
        try {
            DateUtils.setDays(d, 32);
            System.out.println("setDays 32 did not throw");
        } catch (IllegalArgumentException e) { System.out.println("setDays 32 threw IAE"); }

        // ceiling ArithmeticException
        Calendar big = Calendar.getInstance();
        big.set(Calendar.YEAR, 280000001);
        try {
            DateUtils.ceiling(big, Calendar.YEAR);
            System.out.println("ceiling big year did not throw");
        } catch (ArithmeticException e) { System.out.println("ceiling big year threw AE"); }

        // isSameLocalTime with different calendar types
        System.out.println("isSameDay true case: " + DateUtils.isSameDay(d, d));

        // DateIterator NoSuchElementException check
        Calendar s = Calendar.getInstance(); s.clear(); s.set(2020,0,1);
        Calendar e2 = Calendar.getInstance(); e2.clear(); e2.set(2020,0,1);
        Iterator<Calendar> single = DateUtils.iterator(s, DateUtils.RANGE_WEEK_RELATIVE);
        // just count
        int c=0; while(single.hasNext()){single.next(); c++;}
        System.out.println("RANGE_WEEK_RELATIVE count from Jan1 2020 (Wed): " + c);
    }
}
