import org.apache.commons.lang3.time.DateUtils;
import java.util.*;

public class Explore2 {
    public static void main(String[] args) throws Exception {
        TimeZone.setDefault(TimeZone.getTimeZone("America/Los_Angeles"));
        Calendar fc = Calendar.getInstance();
        fc.clear(); fc.set(2008,0,1,7,15,10);
        try {
            DateUtils.getFragmentInDays(fc, Calendar.DAY_OF_WEEK);
            System.out.println("getFragmentInDays DAY_OF_WEEK: no throw");
        } catch (IllegalArgumentException e) { System.out.println("getFragmentInDays DAY_OF_WEEK threw IAE: " + e.getMessage()); }

        try {
            DateUtils.round(fc, Calendar.DAY_OF_WEEK);
            System.out.println("round DAY_OF_WEEK: no throw");
        } catch (IllegalArgumentException e) { System.out.println("round DAY_OF_WEEK threw IAE: " + e.getMessage()); }

        // ceiling to MILLISECOND: should be unchanged
        Calendar c = Calendar.getInstance();
        c.clear(); c.set(2002, Calendar.MARCH, 28, 13, 45, 1);
        c.set(Calendar.MILLISECOND, 231);
        Date d = c.getTime();
        Date ceilMs = DateUtils.ceiling(d, Calendar.MILLISECOND);
        System.out.println("ceiling MILLISECOND same: " + ceilMs.equals(d));

        // iterator invalid range style
        try {
            DateUtils.iterator(Calendar.getInstance(), 999);
            System.out.println("iterator invalid style: no throw");
        } catch (IllegalArgumentException e) { System.out.println("iterator invalid style threw IAE"); }

        // DateIterator remove
        Calendar focus = Calendar.getInstance();
        focus.clear(); focus.set(2020,0,1);
        Iterator<Calendar> it = DateUtils.iterator(focus, DateUtils.RANGE_WEEK_SUNDAY);
        try {
            it.remove();
            System.out.println("remove: no throw");
        } catch (UnsupportedOperationException e) { System.out.println("remove threw UOE"); }
        while (it.hasNext()) it.next();
        try {
            it.next();
            System.out.println("next after exhaustion: no throw");
        } catch (NoSuchElementException e) { System.out.println("next after exhaustion threw NSEE"); }

        // toCalendar with TimeZone
        Calendar cc = DateUtils.toCalendar(d, TimeZone.getTimeZone("UTC"));
        System.out.println("toCalendar tz: " + cc.getTimeZone().getID() + " millis=" + cc.getTimeInMillis() + " dmillis=" + d.getTime());

        // ClassCastException for Object overload
        try {
            DateUtils.ceiling((Object)"not a date", Calendar.YEAR);
            System.out.println("ceiling object bad type: no throw");
        } catch (ClassCastException e) { System.out.println("ceiling object bad type threw CCE"); }

        try {
            DateUtils.iterator((Object)"bad", DateUtils.RANGE_WEEK_SUNDAY);
            System.out.println("iterator object bad type: no throw");
        } catch (ClassCastException e) { System.out.println("iterator object bad type threw CCE"); }

        // parseDate multi pattern fallback
        Date pd = DateUtils.parseDate("2020-01-15", "yyyy/MM/dd", "yyyy-MM-dd");
        System.out.println("parseDate fallback: " + pd);

        // setYears with negative? check javadoc doesn't restrict range except doc; test actual behavior
        try {
            Date r = DateUtils.setYears(d, -5);
            System.out.println("setYears -5: " + r);
        } catch (IllegalArgumentException e) { System.out.println("setYears -5 threw IAE"); }
    }
}
